/**
 * Combat action continuity engine — direct TypeScript port of h3studio's
 * combat_action_engine.py (66KB, pure data transformation, zero UI).
 *
 * Provenance: /mnt/ssd/h3studio/combat_action_engine.py @ 2bc8c907, read-only
 * reference. Function names deliberately mirror the Python source so the two
 * files can be audited side by side; the golden fixtures in
 * combat-fixtures/python-golden.json are generated by running the REAL Python
 * engine (verify/combat/gen-golden.py) and every port behaviour is locked to
 * them — drift dies at test time, not render time.
 *
 * Why rows are loosely typed: the Python engine mutates schemaless plan/shot
 * dicts (user-editable Timeline fields). `PyRow` keeps that shape faithfully;
 * the typed adapter (combat-adapter.ts) is the real boundary slatecrew sees.
 * Crash-path divergence: Python float() raises on garbage where pyFloat falls
 * back — only observable on inputs Python itself would crash on.
 */

export type PyRow = Record<string, unknown>;

// ---- python semantics helpers ---------------------------------------------

/** Python `float(x or fb)` with the source's except-branch fallback folded in. */
function pyFloat(v: unknown, fb: number): number {
  const t = v === undefined || v === null || v === false || v === 0 || v === "" ? fb : v;
  const n = typeof t === "number" ? t : Number(t);
  return Number.isFinite(n) ? n : fb;
}

/** Python `bool(x)` on get-with-False semantics. */
function pyBool(v: unknown): boolean {
  return Boolean(v ?? false);
}

function isRow(v: unknown): v is PyRow {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** Python str.strip / lstrip / rstrip with a character SET (not a substring). */
function stripSet(s: string, chars: string, mode: "both" | "start" | "end" = "both"): string {
  let a = 0;
  let b = s.length;
  const set = new Set([...chars]);
  if (mode === "both" || mode === "start") {
    while (a < b && set.has(s[a]!)) a++;
  }
  if (mode === "both" || mode === "end") {
    while (b > a && set.has(s[b - 1]!)) b--;
  }
  return s.slice(a, b);
}

/** Code points, not UTF-16 units — Python len()/slicing counts code points. */
function cpLen(s: string): number {
  return [...s].length;
}

function cpSlice(s: string, start: number, end?: number): string {
  return [...s].slice(start, end).join("");
}

/** Python round(): half to even, on the exact double. */
function pyRound(x: number): number {
  const fl = Math.floor(x);
  const diff = x - fl;
  if (diff > 0.5) return fl + 1;
  if (diff < 0.5) return fl;
  return fl % 2 === 0 ? fl : fl + 1;
}

/**
 * Python f"{x:.2f}" — correctly rounded decimal of the exact double, ties to
 * even. Doubles ≥ 0.05 have decimal expansions terminating well within 60
 * digits, so toFixed(60) is the exact expansion for this engine's range.
 */
function fmt2(x: number): string {
  const neg = x < 0 || Object.is(x, -0);
  const t = Math.abs(x).toFixed(60);
  const dot = t.indexOf(".");
  const ip = t.slice(0, dot);
  const fp = t.slice(dot + 1);
  let keep = fp.slice(0, 2).padEnd(2, "0");
  const rest = fp.slice(2);
  if (rest.length > 0) {
    const first = rest.charCodeAt(0) - 48;
    const restNonZero = /[1-9]/.test(rest.slice(1));
    let roundUp = first > 5 || (first === 5 && restNonZero);
    if (first === 5 && !restNonZero) {
      const lastDigit = keep.charCodeAt(1) - 48;
      roundUp = lastDigit % 2 === 1;
    }
    if (roundUp) {
      let frac = Number(keep) + 1;
      let int = Number(ip);
      if (frac === 100) {
        frac = 0;
        int += 1;
      }
      keep = String(frac).padStart(2, "0");
      const body = `${int}.${keep}`;
      return (neg && !(int === 0 && frac === 0) ? `-${body}` : body);
    }
  }
  const body = `${ip}.${keep}`;
  return neg && !(Number(ip) === 0 && Number(keep) === 0) ? `-${body}` : body;
}

function pad2(n: number): string {
  return String(Math.trunc(n)).padStart(2, "0");
}

function collapseWs(s: string): string {
  return s.split(/\s+/).filter((w) => w !== "").join(" ");
}

function dedupe<T>(list: T[]): T[] {
  return [...new Set(list)];
}

