  /single[- ]leg|double[- ]leg|captures?\s+(?:the\s+)?leg|takedown|抱腿|抱摔/i;
const TOP_CONTROL_RE =
  /side control|mount(?:ed)?|top control|ground[- ]and[- ]pound|上位压制|上位壓制|侧压|側压/i;
